use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (result: Vec<u64>)
    requires
        a.len() <= 100,
        b.len() <= 100,
    ensures
        result.len() == a.len() + b.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
        forall|i: int| a.len() <= i < result.len() ==> result[i] == b[i - a.len()],
{
    let mut result = Vec::new();
    let mut idx: usize = 0;
    
    while idx < a.len()
        invariant
            idx <= a.len(),
            result.len() == idx,
            forall|i: int| 0 <= i < idx ==> result[i] == a[i],
    {
        result.push(a[idx]);
        idx = idx + 1;
    }
    
    let mut idx2: usize = 0;
    while idx2 < b.len()
        invariant
            idx2 <= b.len(),
            result.len() == a.len() + idx2,
            forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
            forall|i: int| a.len() <= i < result.len() ==> result[i] == b[i - a.len()],
    {
        result.push(b[idx2]);
        idx2 = idx2 + 1;
    }
    
    result
}

}

